/// <summary>Q1676–Q1745: batch 29 containment/ending bar (schema 31).</summary>
public class HatchContainmentEndingBarLaterTests
{
    [Fact] public void Q1676_containment_1676() { var g = Game.Solo(); int baseWork = TrainingSystem.AlignmentWorkPermille(g.C, g.Me); g.Me.Rooms.Add(new RoomState { Id = g.State.TakeId(), TypeId = "containment-wing", X = 8, Y = 0, Width = 4, Height = 4 }); Assert.True(LabQueries.ContainmentAlignmentBonus(g.C, g.Me) > 0); }
    [Fact] public void Q1677_containment_1677() { GameConfig c = TestData.Config(); Assert.Contains(c.RoomTypes, r => r.Id == "containment-wing"); Assert.Equal(31, new Game(Simulation.NewGame(c, new NewGameOptions { Seed = 3001 })).State.Schema); }
    [Fact] public void Q1678_containment_1678() { var g = Game.Solo(seed: 3102); SaveSchemaPretend.AssertRoundTrip(g.Sim); Assert.True(g.C.Endings.Superintelligence != null); }
